fn prime_num(n: u64) -> bool {
    // Handle small cases
    if n == 2 {
        return true;
    }
    
    // Even numbers > 2 are composite
    if n % 2 == 0 {
        return false;
    }
    
    // Check odd divisors up to sqrt(n)
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    
    true
}